import type { MaterializedEntity } from "./contracts";
import { NEUTRAL_DYNAMICS } from "./entity-dynamics";
import type { UniverseView } from "./universe-state";

// Demo fixture for the audio-loop feature: two `thing`s that point to audio
// files. In a real Universe the `audio` facet is projected from graph content by
// desktop_world_snapshot.rs (resolve_audio); here it is inlined so the feature is
// audible in the shell without shipping a binary asset. The two clips are seamless
// (an integer number of periods), so `loop` produces a continuous tone.
//
// Generated by a one-off script: 8-bit mono WAV, 8000 Hz, 0.4 s.
//   chime = 400 Hz, drone = 140 Hz.
const CHIME_SRC =
  "data:audio/wav;base64,";
const DRONE_SRC =
  "data:audio/wav;base64,";

function audioThing(
  id: string,
  position: [number, number, number],
  color: string,
  src: string,
  gain: number
): MaterializedEntity {
  return {
    id,
    generation: 0,
    position,
    visual: {
      primitive: "pulsing_core",
      motion: "outward_pulse",
      material: {
        color,
        emissive: color,
        emissiveIntensity: 2.2,
        opacity: 0.9,
        scale: 1
      }
    },
    dynamics: NEUTRAL_DYNAMICS,
    audio: { src, loop: true, gain }
  };
}

export const AUDIO_CHIME_ID = "fixture:thing:chime";
export const AUDIO_DRONE_ID = "fixture:thing:drone";

export function audioFixtureUniverse(): UniverseView {
  const chime = audioThing(AUDIO_CHIME_ID, [-2.2, 0, 0], "#8fe3ff", CHIME_SRC, 0.6);
  const drone = audioThing(AUDIO_DRONE_ID, [2.2, 0, 0], "#ffb0d6", DRONE_SRC, 0.45);
  return {
    revision: 1,
    sequence: 0,
    synchronized: true,
    entities: new Map([
      [chime.id, chime],
      [drone.id, drone]
    ]),
    relations: new Map(),
    transfers: new Map(),
    control: { kind: "observer" },
    available_actions: []
  };
}
